<?php require_once 'db.php'; require_login(); csrf_check(); $page_title='Reserve'; $s=db()->prepare("SELECT id, name, description AS detail, price, stock FROM cakes WHERE id=?");$s->execute([(int)($_GET['id']??$_POST['id']??0)]);$item=$s->fetch();if(!$item){flash('Item not found.');go('catalog.php');}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){if((int)$item['stock']<1){$err='No availability remaining for this item.';}else{try{$detail=$_POST['option'].' size · Message: '.trim($_POST['message']??'').' · Address: '.trim($_POST['address']);$amount=(float)$item['price'];$s=db()->prepare("INSERT INTO bookings(user_id,item_id,item_name,details,amount,status) VALUES(?,?,?,?,?,?)");$s->execute([$_SESSION['user_id'],$item['id'],$item['name'],$detail,$amount,'Confirmed']);$u=db()->prepare("UPDATE cakes SET stock=stock-1 WHERE id=? AND stock>0");$u->execute([$item['id']]);flash('Cake order placed. Payment is simulated for this lab.');go('payment.php?id='.db()->lastInsertId());}catch(Throwable $e){$err='Could not save your reservation. Please retry.';}}} include 'header.php'; ?>
<section class="section" style="max-width:760px;margin:auto"><div class="eyebrow">STEP 1 · DETAILS</div><h1 style="font-size:3rem">Complete your selection.</h1><?php if($err): ?><div class="notice"><?= h($err) ?></div><?php endif; ?><div class="panel"><h2><?= h($item['name']) ?></h2><p class="muted"><?= h($item['detail']) ?></p><div class="price">₹<?= number_format($item['price'],0) ?></div><form method="post"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><div class="field"><label>Size</label><select name="option"><option>Small</option><option>Medium</option><option>Large</option></select></div><div class="field"><label>Message on cake</label><input name="message" maxlength="100" placeholder="Happy Birthday!"></div><div class="field"><label>Delivery address</label><input name="address" required></div><button class="btn">Confirm details</button></form></div></section><?php include 'footer.php'; ?>